/bin/bash -lc "python3 - <<'EOF'
import numpy as np
from PIL import Image
a = np.array(Image.open('first_frame.png')).astype(int)
H,W,_=a.shape
r,g,b = a[...,0],a[...,1],a[...,2]
mx=a.max(2); mn=a.min(2)
cloth = (mn>150)&((mx-mn)<40)
orange = (r>g+25)&(r>b+25)&(r>60)

def comps(mask, min_size=20):
    lab=-np.ones((H,W),dtype=np.int32); n=0; out=[]
    for sy in range(H):
        for sx in range(W):
            if mask[sy,sx] and lab[sy,sx]<0:
                stack=[(sy,sx)]; lab[sy,sx]=n; cnt=0
                x0=x1=sx;y0=y1=sy; sxsum=0; sysum=0
                while stack:
                    y,x=stack.pop(); cnt+=1; sxsum+=x; sysum+=y
                    x0=min(x0,x);x1=max(x1,x);y0=min(y0,y);y1=max(y1,y)
                    for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<H and 0<=nx<W and mask[ny,nx] and lab[ny,nx]<0:
                            lab[ny,nx]=n; stack.append((ny,nx))
                if cnt>=min_size: out.append((cnt,(x0,y0,x1,y1),(sxsum//cnt,sysum//cnt)))
                n+=1
    return sorted(out,reverse=True)

print(\"WHITE components:\")
for c in comps(cloth,30)[:10]: print(c)
print(\"ORANGE components:\")
for c in comps(orange,40)[:10]: print(c)

# check connectivity: are top cloth and side whites connected?
lab=-np.ones((H,W),dtype=np.int32); n=0
for sy in range(H):
    for sx in range(W):
        if cloth[sy,sx] and lab[sy,sx]<0:
            stack=[(sy,sx)]; lab[sy,sx]=n
            while stack:
                y,x=stack.pop()
                for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    ny,nx=y+dy,x+dx
                    if 0<=ny<H and 0<=nx<W and cloth[ny,nx] and lab[ny,nx]<0:
                        lab[ny,nx]=n; stack.append((ny,nx))
            n+=1
# label at probe points
for name,(x,y) in {\"top_cloth\":(120,15),\"left\":(25,90),\"right\":(230,55),\"top_right\":(190,30)}.items():
    print(name, \"label\", lab[y,x])
EOF"
